"""Term registry of the skill: one name, one definition and one source per quantity (assets/terms.yaml).

The registry is the source of the names. From it come:

* the labels the pages use (`label`, `short`), so a quantity has the same name in the exploration pages, the
  dashboard, `summarize` and the report;
* `references/glossary.md`, generated by `glossary_md` (never edited by hand), which the agent reads before
  explaining a number;
* the term check (`lint`): a name listed as deprecated for a quantity must not appear in the code or the
  documentation any more;
* the dependency drift note (`dependency_drift`): an entry records the hash of the dependency skill its
  definition was checked against, and `expression.py check` says when the installed skill differs.

Library: Term, TermError, load, conventions, undecided, label, short, glossary_md, lint, check, dependency_drift.
"""

from __future__ import annotations

import dataclasses
import json
import re
from pathlib import Path
from typing import Any

import yaml

SKILL_DIR = Path(__file__).resolve().parent.parent
REGISTRY = SKILL_DIR / "assets" / "terms.yaml"
GLOSSARY = SKILL_DIR / "references" / "glossary.md"
KINDS = ("api", "derived")
STATUSES = ("official", "skill_convention", "undecided")
CERTAINTIES = ("stated", "inferred", "not_found")
STATUS_TEXT = {"official": "official (stated by a source)", "skill_convention": "this skill's convention",
               "undecided": "undecided (no source consulted settles it)"}
REQUIRED = ("id", "kind", "api", "label_pt", "label_en", "definition", "unit", "comparable", "status", "source")
OK_MARK = "term-ok"  # a line with this mark is not checked (a legitimate use of the word in another sense)
# What the term check reads: the code that writes text for the researcher, and the documentation the agent reads.
LINT_GLOBS = ("scripts/*.py", "scripts/core/*.py", "scripts/viz/*.py", "assets/dashboard.py", "SKILL.md", "references/*.md")
LINT_SKIP = ("references/glossary.md", "scripts/terms.py")


class TermError(Exception):
    """The registry is malformed, or a name it deprecates is still in use."""


@dataclasses.dataclass(frozen=True)
class Term:
    """One quantity of the registry (see the header of assets/terms.yaml for the fields)."""

    id: str
    kind: str
    api: dict[str, Any]
    label_pt: str
    label_en: str
    definition: str
    unit: str
    comparable: str
    status: str
    source: dict[str, Any]
    short_pt: str | None = None
    formula: str | None = None
    note: str | None = None
    deprecated_pt: tuple[str, ...] = ()
    deprecated_en: tuple[str, ...] = ()


_CACHE: dict[Path, tuple[dict[str, Term], list[str]]] = {}


def load(path: Path = REGISTRY) -> dict[str, Term]:
    """The registry as {id: Term}; raises TermError when an entry lacks a field, a source or a valid status."""
    return _load(path)[0]


def conventions(path: Path = REGISTRY) -> list[dict[str, str]]:
    """How names and numbers are written (genes, proteins, variants, coordinates, Portuguese numbers)."""
    try:
        raw = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    except (OSError, yaml.YAMLError) as exc:
        raise TermError(f"{path}: cannot read the term registry ({exc})") from exc
    out = raw.get("conventions") or []
    for c in out:
        if not isinstance(c, dict) or not all(c.get(k) for k in ("what", "rule", "example", "source")):
            raise TermError(f"{path}: each convention needs what, rule, example and source")
    return out


def undecided(path: Path = REGISTRY) -> list[str]:
    """The questions no consulted source settles, as the registry lists them."""
    return _load(path)[1]


def _load(path: Path) -> tuple[dict[str, Term], list[str]]:
    if path in _CACHE:
        return _CACHE[path]
    try:
        raw = yaml.safe_load(path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError) as exc:
        raise TermError(f"{path}: cannot read the term registry ({exc})") from exc
    if not isinstance(raw, dict) or not isinstance(raw.get("terms"), list):
        raise TermError(f"{path}: expected a mapping with a `terms` list")
    fields = {f.name for f in dataclasses.fields(Term)}
    out: dict[str, Term] = {}
    for n, entry in enumerate(raw["terms"], 1):
        if not isinstance(entry, dict):
            raise TermError(f"{path}: entry {n} is not a mapping")
        ident = entry.get("id", f"#{n}")
        missing = [f for f in REQUIRED if entry.get(f) in (None, "", {})]
        if missing:
            raise TermError(f"{path}: term '{ident}' lacks {', '.join(missing)}")
        extra = set(entry) - fields
        if extra:
            raise TermError(f"{path}: term '{ident}' has unknown field(s) {sorted(extra)}")
        if entry["kind"] not in KINDS:
            raise TermError(f"{path}: term '{ident}': kind must be one of {KINDS}")
        if entry["status"] not in STATUSES:
            raise TermError(f"{path}: term '{ident}': status must be one of {STATUSES}")
        src = entry["source"]
        if not isinstance(src, dict) or not src.get("doc") or src.get("certainty") not in CERTAINTIES:
            raise TermError(f"{path}: term '{ident}': source needs `doc` and `certainty` (one of {CERTAINTIES})")
        if bool(src.get("checked_skill")) != bool(src.get("checked_hash")):
            raise TermError(f"{path}: term '{ident}': checked_skill and checked_hash go together")
        if ident in out:
            raise TermError(f"{path}: term id '{ident}' appears twice")
        body = dict(entry)
        for key in ("deprecated_pt", "deprecated_en"):
            body[key] = tuple(str(x) for x in body.get(key) or ())
        out[ident] = Term(**body)
    labels: dict[str, str] = {}
    for t in out.values():
        if t.label_pt in labels:
            raise TermError(f"{path}: '{t.label_pt}' names both '{labels[t.label_pt]}' and '{t.id}'; one name per quantity")
        labels[t.label_pt] = t.id
    _CACHE[path] = (out, [str(x) for x in raw.get("undecided") or []])
    return _CACHE[path]


def label(term_id: str, lang: str = "pt") -> str:
    """The name of a quantity, as the researcher reads it (`pt`) or as the documentation writes it (`en`)."""
    t = load().get(term_id)
    if t is None:
        raise TermError(f"no term '{term_id}' in {REGISTRY.name}")
    return t.label_pt if lang == "pt" else t.label_en


def short(term_id: str) -> str:
    """The short Portuguese name for a table header (the full name when the entry has no short one)."""
    t = load().get(term_id)
    if t is None:
        raise TermError(f"no term '{term_id}' in {REGISTRY.name}")
    return t.short_pt or t.label_pt


def cap(text: str) -> str:
    """First letter in upper case, the rest as written (for a heading or a column header)."""
    return text[:1].upper() + text[1:]


# --------------------------------------------------------------------------- glossary


def _api(t: Term) -> str:
    a = t.api
    if "scorer" in a:
        return f"scorer `{a['scorer']}`, {a.get('column', '')}".rstrip(", ")
    return str(a.get("source") or a.get("field") or "")


def glossary_md(path: Path = REGISTRY) -> str:
    """references/glossary.md, written from the registry."""
    terms, open_points = _load(path)
    L = ["# Glossary (generated from `assets/terms.yaml`; do not edit by hand)", "",
         "One name per quantity. Read this before explaining a number to the researcher: say what it is, relative to",
         "what, in what unit, and its status. For an entry marked *undecided*, say that it is not established; do not",
         "infer. The Portuguese name is the one the pages show; use it as written. For the full definition of a score,",
         "read the document named in *Source* (for the AlphaGenome scores, the `alphagenome` dependency skill).", "",
         "Regenerate after changing the registry: `expression.py terms --write-glossary`. `expression.py terms --check`",
         "fails when a deprecated name is still in the code or the documentation.", "",
         "## Names", "",
         "| Name on the pages (Portuguese) | In the documentation (English) | Comes from | Status |",
         "|---|---|---|---|"]
    for t in terms.values():
        L.append(f"| {t.label_pt} | {t.label_en} | {_api(t)} | {STATUS_TEXT[t.status]} |")
    L += ["", "## Definitions", ""]
    for t in terms.values():
        L += [f"### {t.label_pt} ({t.label_en})", "", f"- **What it is:** {t.definition}"]
        if t.formula:
            L.append(f"- **Formula:** `{t.formula}`")
        L += [f"- **Unit:** {t.unit}", f"- **Comparable with:** {t.comparable}", f"- **Comes from:** {_api(t)}",
              f"- **Status:** {STATUS_TEXT[t.status]}",
              f"- **Source:** {t.source['doc']} ({t.source['certainty'].replace('_', ' ')})"]
        if t.note:
            L.append(f"- **Say with it:** {t.note}")
        old = [*t.deprecated_pt, *t.deprecated_en]
        if old:
            L.append("- **Names no longer used for it:** " + "; ".join(f"\"{x}\"" for x in old))
        L.append("")
    rules = conventions(path)
    if rules:
        L += ["## Writing conventions", "",
              "How names and numbers are written on the pages; write them the same way in your answers.", "",
              "| What | Rule | Example | Source |", "|---|---|---|---|"]
        L += [f"| {c['what']} | {c['rule']} | {c['example']} | {c['source']} |" for c in rules]
        L.append("")
    if open_points:
        L += ["## Not decided by any source consulted", "",
              "State these as open when the researcher asks; a rewording does not settle them.", ""]
        L += [f"- {x}" for x in open_points]
        L.append("")
    return "\n".join(L)


# --------------------------------------------------------------------------- checks


def _pattern(phrase: str) -> re.Pattern[str]:
    """The phrase as a whole word or phrase, any case ("ruído" does not match "reconstruído")."""
    return re.compile(r"(?<![\w])" + re.escape(phrase) + r"(?![\w])", flags=re.IGNORECASE)


def lint(skill_dir: Path = SKILL_DIR, path: Path = REGISTRY) -> list[str]:
    """Uses of a deprecated name in the code or the documentation, as 'file:line: "name" (use "<label>")'."""
    terms = load(path)
    rules = [(_pattern(p), p, t) for t in terms.values() for p in (*t.deprecated_pt, *t.deprecated_en)]
    found: list[str] = []
    files = sorted({f for g in LINT_GLOBS for f in skill_dir.glob(g)})
    for f in files:
        rel = f.relative_to(skill_dir).as_posix()
        if rel in LINT_SKIP:
            continue
        for n, line in enumerate(f.read_text(encoding="utf-8").splitlines(), 1):
            if OK_MARK in line:
                continue
            for pat, phrase, t in rules:
                if pat.search(line):
                    found.append(f"{rel}:{n}: \"{phrase}\" (use \"{t.label_pt}\" / \"{t.label_en}\")")
    return found


def check(skill_dir: Path = SKILL_DIR) -> list[str]:
    """Every problem of the registry and its use: a malformed entry, a deprecated name in use, a stale glossary."""
    try:
        load()
    except TermError as exc:
        return [str(exc)]
    problems = lint(skill_dir)
    glossary = skill_dir / "references" / "glossary.md"
    if not glossary.is_file():
        problems.append("references/glossary.md is missing: run expression.py terms --write-glossary")
    elif glossary.read_text(encoding="utf-8").replace("\r\n", "\n") != glossary_md():
        problems.append("references/glossary.md is out of date with assets/terms.yaml: run expression.py terms --write-glossary")
    return problems


def dependency_drift(workspace: Path | None) -> list[str]:
    """Dependency skills whose installed version differs from the one a definition was checked against
    (the workspace's skills-lock.json against `checked_hash`); empty when there is no lock file."""
    if workspace is None or not (workspace / "skills-lock.json").is_file():
        return []
    try:
        lock = json.loads((workspace / "skills-lock.json").read_text(encoding="utf-8")).get("skills", {})
    except (OSError, ValueError):
        return []
    checked: dict[str, set[str]] = {}
    for t in load().values():
        if t.source.get("checked_skill"):
            checked.setdefault(t.source["checked_skill"], set()).add(t.source["checked_hash"])
    notes = []
    for name, hashes in sorted(checked.items()):
        installed = (lock.get(name) or {}).get("computedHash")
        if installed and installed not in hashes:
            used = sorted(t.id for t in load().values() if t.source.get("checked_skill") == name)
            notes.append(f"the installed '{name}' skill differs from the version the term registry was checked against; "
                         f"review these definitions in assets/terms.yaml: {', '.join(used)}")
    return notes
